@import url('https://testingcf.jsdelivr.net/npm/@fontsource/eb-garamond@5.1.0/400.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/eb-garamond@5.1.0/400-italic.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/figtree@5.1.0/500.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/figtree@5.1.0/600.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/figtree@5.1.0/700.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.1.0/700.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.1.0/400.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/noto-sans-sc@5.1.0/500.css');
@import url('https://testingcf.jsdelivr.net/npm/@fontsource/noto-sans-sc@5.1.0/700.css');
@import url('https://fontsapi.zeoseven.com/438/main/result.css');
@import url('https://fontsapi.zeoseven.com/159/main/result.css');
@import url('https://testingcf.jsdelivr.net/npm/lxgw-wenkai-webfont@1.7.0/lxgwwenkai-regular.css');
/* ================================================================
 * 絮语 Murmur —— 奶油色的纸，慢慢说话
 *
 * 作者：mangosagocreamwithpomelo（Discord）
 * 设计与实现：Claude Opus 5.5（Anthropic）
 * 配色和字体的规矩借鉴 Wispr Flow 的网站（奶油、墨、深绿和四种亮色；西文衬线大字配斜体），
 * 不含它的商标、图标和图片。
 *
 * 昼 / 夜：
 *   只装主题 → 跟随系统（浅色模式是奶油纸，深色模式是深绿）
 *   装「主题伴侣」扩展 → 手动切换、按时间切换
 *
 * 改颜色：
 *   夜版 → 「用户设置 → UI 主题」的颜色选择器
 *   昼版 → 下面可改区的 --xy-day-* 几行
 *
 * 字体：
 *   西文 Figtree / EB Garamond / JetBrains Mono（OFL），中文思源宋体、思源黑体（OFL），
 *   汇文正楷（TerryWang，免费商用、禁止牟利），更纱等宽（OFL），霞鹜文楷（OFL）。
 *   正文中文优先用你设备上装好的 MiSans（小米，© Xiaomi）；没装就用思源黑体。
 *   汇文正楷、更纱等宽由 ZeoSeven Fonts 托管。
 * ================================================================ */

/* ================================================================
 * 可改区：想调整的都在这里，改完点空白处即可生效。改坏了重新导入主题就能恢复。
 * ================================================================ */
html:root {
    /* —— 昼版配色（夜版在 UI 主题的颜色选择器里改）—— */
    --xy-day-paper: #FFFFEB;           /* 纸：聊天区、面板 */
    --xy-day-card: #E4E4D0;            /* 压一档的奶油：卡片、输入框、行内代码底 */
    --xy-day-ink: #1A1A1A;             /* 唯一的字色 */
    --xy-day-em: rgba(26, 26, 26, 0.7);   /* 心理描写、次要字：墨 70% */
    --xy-day-line: rgba(26, 26, 26, 0.15); /* 细线 */
    --xy-day-label: #034F46;           /* 小标签的字（深绿） */
    --xy-day-code: #034F46;            /* 代码块的底（深绿，字是奶油色） */
    --xy-day-stage: #E4E4D0;           /* 聊天区：纸上一块灰色大圆角底 */
    --xy-day-sheet: #F5F4F0;           /* 角色消息的字铺在这层浅色上（想露出奶油色就填 #FFFFEB） */

    /* —— 两版共用的亮色 —— */
    --xy-flare: #FF6C4C;               /* 橘红：开着的条目、打开的图标、发送、生成中。夜版的在 UI 主题「底线文字」里 */
    --xy-night-label: #FFA946;         /* 夜版小标签的字（杏黄） */
    --xy-night-code: #1A1A1A;          /* 夜版代码块的底（墨） */
    --xy-night-stage: #02403A;         /* 夜版聊天区的底：比纸深一档 */
    --xy-night-sheet: #0B5A50;         /* 夜版角色消息的那层：比纸浅一档 */

    /* —— 名字的颜色 ——
       -c 是胶囊和气泡的底色；-ink 是压在上面的字；-t 是「彩色名字」样式里名字本身的颜色（昼 / 夜各一个，要够清楚） */
    --xy-char-c: #FFA946;              /* 角色：杏黄 */
    --xy-char-ink: #1A1A1A;
    --xy-char-t-day: #8A4B00;
    --xy-char-t-night: #FFA946;
    --xy-you-c: #F0D7FF;               /* 你：淡紫 */
    --xy-you-ink: #1A1A1A;
    --xy-you-t-day: #6E3FA6;
    --xy-you-t-night: #F0D7FF;

    /* —— 开关 —— */
    --xy-name: pill;                   /* 名字：pill 胶囊 / text 彩色名字 / avatar 圆头像（Firefox 只有胶囊） */
    --xy-layout: stage;                /* 底：stage = 聊天区一整块灰底、角色消息铺浅色层；cards = 聊天区是纸，角色消息各一张灰卡片，字露出纸色 */
    --xy-bubble: 1;                    /* 你的消息放进气泡：1 开 / 0 关 */

    /* —— 字体 —— */
    --xy-sans: 'Figtree', 'XY MiSans', 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif;
    --xy-sans-bold: 'Figtree', 'XY MiSans', 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif;
    --xy-kai: 'Huiwen-ZhengKai';       /* 斜体的替身（中文没有斜体）。想换霞鹜文楷：'LXGW WenKai' */
    --xy-kai-85: 'XY Kai 85';          /*   大字里用的缩小版。换霞鹜文楷：'XY WenKai 85' */
    --xy-display: 'EB Garamond', 'XY Serif SC 85', 'Noto Serif SC', 'Songti SC', serif;      /* 大字 */
    --xy-display-alt: 'EB Garamond', var(--xy-kai-85), var(--xy-kai), 'KaiTi', serif;         /* 大字的后半句（斜体） */
    --xy-em-font: 'EB Garamond', var(--xy-kai), 'KaiTi', serif;                               /* 心理描写 */
    --xy-label-font: 'JetBrains Mono', 'Sarasa Mono SC', 'Noto Sans SC', monospace;           /* 小标签 */
    --xy-code-font: 'Sarasa Mono SC', 'JetBrains Mono', monospace;                            /* 代码 */

    /* —— 正文 —— */
    --xy-read-size: calc(var(--mainFontSize) * 1.0);
    --xy-read-weight: 500;
    --st-mes-line-height: 1.8;         /* 行高 */
    --st-mes-paragraph-gap: 0.75em;    /* 段落间距 */
    --st-mes-padding-inline: 0px;      /* 正文左右留白 */
    --xy-measure: 40;                  /* 一行最多约几个字 */

    /* —— 版面 —— */
    --xy-pad-top: 18px;                /* 每条消息上方 */
    --xy-pad-bottom: 18px;             /* 每条消息下方 */
    --xy-pad-left: 22px;               /* 消息左边 */
    --xy-pad-right: 22px;              /* 消息右边 */
    --xy-avatar: 40px;                 /* 圆头像样式的头像大小 */
    --xy-radius: 28px;                 /* 大圆角：面板、卡片 */
    --xy-mes-buttons-idle: 0;          /* 电脑上消息右上角的按钮：0 = 鼠标移上去才出现，1 = 一直显示 */

    /* —— 大字 —— */
    --xy-welcome-big: '零点以后，';     /* 欢迎页照片上的大字（前半句） */
    --xy-welcome-alt: '慢慢说';         /* 后半句：斜体，下面一道淡紫线 */
    --xy-splash-big: '絮语';           /* 启动页 */
    --xy-splash-alt: 'Murmur';
    --xy-cover-label: '开篇';          /* 聊天第一条消息上方（扉页）那行小字 */
}

@media screen and (max-width: 1000px) {
    html:root {
        --xy-pad-top: 14px;
        --xy-pad-bottom: 14px;
        --xy-pad-left: 12px;
        --xy-pad-right: 16px;
        --xy-radius: 22px;
    }
}
/* ======================== 可改区结束 ======================== */

/* ==== themes/xuyu/base.css ==== */
/* ================================================================
 * 絮语 · 母版（夜：深绿）
 * 颜色只有一种字色（夜是奶油，昼是墨），灰字就是字色 70%；亮色（淡紫、粉、杏黄、橘红）只当底，不当字。
 *   夜：纸 深绿 #034F46 · 面板 #02403A · 字 奶油 · 小标签 杏黄 · 代码块 墨底
 *   昼：纸 奶油 #FFFFEB · 卡片 #E4E4D0 · 字 墨 · 小标签 深绿 · 代码块 深绿底
 * 橘红只做「开着 / 当前 / 在动」的记号。昼版只覆盖色板，见 day.css。
 * ================================================================ */
/* ==== shared/layout-vars.css ==== */
/* 留白与排版变量：用户只需改这里即可全局生效（碎碎念第 3 条） */
:root {
    --st-mes-padding-inline: 14px;   /* 正文左右留白 */
    --st-mes-padding-block: 6px;     /* 正文上下留白 */
    --st-mes-line-height: 1.7;       /* 正文行高 */
    --st-mes-paragraph-gap: 0.6em;   /* 段落间距 */
}

.mes_text {
    padding-inline: var(--st-mes-padding-inline) !important;
    padding-block: var(--st-mes-padding-block) !important;
    line-height: var(--st-mes-line-height);
}

.mes_text p {
    margin-block: 0 var(--st-mes-paragraph-gap);
}

.mes_text p:last-child {
    margin-block-end: 0;
}
/* ==== end shared/layout-vars.css ==== */
/* ==== shared/scrollbar.css ==== */
/* 滚动条：PC 端始终可见且跟随主题色；仅手机端隐藏（碎碎念第 4 条） */
::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
    background-color: color-mix(in srgb, var(--SmartThemeBodyColor) 35%, transparent);
    box-shadow: none;
}

::-webkit-scrollbar-thumb:vertical:hover,
::-webkit-scrollbar-thumb:horizontal:hover {
    background-color: color-mix(in srgb, var(--SmartThemeBodyColor) 55%, transparent);
}

@media screen and (max-width: 1000px) and (pointer: coarse) {
    ::-webkit-scrollbar {
        width: 0;
        height: 0;
    }
}
/* ==== end shared/scrollbar.css ==== */
/* ==== shared/entry-states.css ==== */
/* 世界书 / 预设条目的开关态（碎碎念第 1 条）
 * 酒馆默认：禁用世界书条目 opacity:.4 + 灰度；禁用预设名称写死 white30a，都会让标题看不清。
 * 这里改成：标题始终保持可读，用「左侧线条（颜色 + 线型）+ 背景 + 开关图标」多重信号区分开/关。
 * 主题可覆盖下列变量调整外观（颜色默认从 SmartTheme 变量派生，不写死）。
 * 默认外观 = 「斜纹底 + 斜体标题」（用户认可的设计，存档供以后的主题使用）。 */
:root {
    --st-entry-on: var(--SmartThemeQuoteColor);            /* 启用 */
    --st-entry-constant: var(--SmartThemeUnderlineColor);  /* 常驻（蓝灯） */
    --st-entry-off: color-mix(in srgb, var(--SmartThemeBodyColor) 35%, transparent); /* 禁用线条 */
    --st-entry-off-bg: repeating-linear-gradient(-45deg,
        color-mix(in srgb, var(--SmartThemeBodyColor) 5%, transparent) 0 6px,
        transparent 6px 12px);
    --st-entry-bar: 4px;
    /* 线型：图例式区分（double 需要 bar ≥ 3px 才看得出） */
    --st-entry-on-style: solid;
    --st-entry-constant-style: solid;
    --st-entry-off-style: dashed;
    /* 禁用条目标题 */
    --st-entry-off-title-color: var(--SmartThemeBodyColor);
    --st-entry-off-title-style: italic;
    --st-entry-radius: 6px;
}

/* ---------- 世界书 ---------- */
#world_popup_entries_list .world_entry {
    border-left: var(--st-entry-bar) var(--st-entry-on-style) var(--st-entry-on);
    border-radius: var(--st-entry-radius);
}

/* 常驻但已关闭的条目按「关闭」显示 */
#world_popup_entries_list .world_entry:not(.disabledWIEntry):has(select[name="entryStateSelector"] option[value="constant"]:checked) {
    border-left-width: var(--st-entry-constant-bar, var(--st-entry-bar));
    border-left-style: var(--st-entry-constant-style);
    border-left-color: var(--st-entry-constant);
}

#world_popup_entries_list .world_entry.disabledWIEntry,
#world_popup_entries_list .world_entry.disabledWIEntry:hover {
    opacity: 1;
    filter: none;
    border-left-style: var(--st-entry-off-style);
    border-left-color: var(--st-entry-off);
    background-image: var(--st-entry-off-bg);
}

#world_popup_entries_list .world_entry.disabledWIEntry textarea[name="comment"] {
    color: var(--st-entry-off-title-color);
    font-style: var(--st-entry-off-title-style);
}

/* 开关图标：开 = 实心主题色、不透明；关 = 正文色淡化。酒馆默认给图标 opacity .4，会让「开」反而比「关」暗 */
#world_popup_entries_list .world_entry .killSwitch.fa-toggle-on {
    color: var(--st-entry-on);
    opacity: 1;
}

#world_popup_entries_list .world_entry .killSwitch.fa-toggle-off {
    color: var(--SmartThemeBodyColor);
    opacity: 0.55;
}

/* ---------- 预设（Prompt Manager） ---------- */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    border-radius: var(--st-entry-radius);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    border-left: var(--st-entry-bar) var(--st-entry-on-style) var(--st-entry-on);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    border: 1px var(--st-entry-off-style) var(--st-entry-off);
    border-left-width: var(--st-entry-bar);
    background-image: var(--st-entry-off-bg);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--st-entry-off-title-color);
    font-style: var(--st-entry-off-title-style);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--st-entry-on);
    opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action {
    color: var(--SmartThemeBodyColor);
    opacity: 0.55;
}
/* ==== end shared/entry-states.css ==== */
/* ==== shared/st-fixes.css ==== */
/* 酒馆界面的通用修正（从「纸上访谈」沉淀出来，第二套主题「银盐」起使用）
 * 酒馆很多按钮、图标、菜单默认半透明、带黑色模糊投影或暗红/绿色底，换了主题配色也发灰发脏。
 * 这里统一成实色，颜色全部来自下面几个变量，主题在自己的 :root 里改它们即可：
 *   --fx-ink      正文色            --fx-meta     次要文字
 *   --fx-accent   强调色            --fx-on-accent 强调色实底上的字
 *   --fx-hairline 细线              --fx-surface  输入框等浅底
 *   --fx-radius   圆角 */
:root {
    --fx-ink: var(--SmartThemeBodyColor);
    --fx-meta: color-mix(in srgb, var(--SmartThemeBodyColor) 62%, transparent);
    --fx-accent: var(--SmartThemeUnderlineColor);
    --fx-on-accent: var(--SmartThemeChatTintColor);
    --fx-hairline: var(--SmartThemeBorderColor);
    --fx-surface: color-mix(in srgb, var(--SmartThemeBodyColor) 4%, transparent);
    --fx-radius: 0;
    --fx-mes-buttons-idle: 0;   /* 电脑上消息按钮：0 = 鼠标移上去才出现，1 = 一直显示 */
}

/* ---- 消息按钮：电脑上悬停才出现；本身改成实色小图标（默认 30% 透明 + 黑色模糊投影） ---- */
@media (hover: hover) {
    #chat .mes .mes_buttons {
        opacity: var(--fx-mes-buttons-idle);
        transition: opacity 0.2s;
    }

    #chat .mes:hover .mes_buttons,
    #chat .mes .mes_buttons:focus-within {
        opacity: 1;
    }
}

#chat .mes .mes_button,
#chat .mes .extraMesButtons > div {
    opacity: 1;
    filter: none;
    color: var(--fx-meta);
    transition: color 0.2s;
}

#chat .mes .mes_button:hover,
#chat .mes .extraMesButtons > div:hover {
    color: var(--fx-accent);
}

/* 编辑消息时的按钮：默认绿底、红底 → 细线框；「完成」用强调色实底 */
#chat .mes .mes_edit_buttons .menu_button,
#chat .mes .mes_reasoning_edit_cancel,
#chat .mes .mes_reasoning_edit_done {
    background-color: transparent;
    opacity: 1;
    filter: none;
    color: var(--fx-meta);
}

#chat .mes .mes_edit_buttons .mes_edit_done,
#chat .mes .mes_reasoning_edit_done {
    background-color: var(--fx-accent);
    border-color: var(--fx-accent);
    color: var(--fx-on-accent);
}

/* 其余写死的黑色模糊投影（编辑按钮、展开按钮、收藏星标、图片计数、关闭叉） */
.mes_edit_buttons,
.extraMesButtons > div,
.ch_fav_icon,
.mes_img_swipe_counter,
.dragClose {
    filter: none;
}

/* ---- 预设条目里的小图标：默认 40% 透明 + 投影 ---- */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span,
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
    opacity: 1;
    color: var(--fx-meta);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span:hover {
    color: var(--fx-accent);
}

#completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action.fa-toggle-on {
    color: var(--fx-accent);
}

#completion_prompt_manager .caution {
    color: var(--fx-accent);
}

/* ---- 按钮 ---- */
.menu_button {
    background-color: transparent;
    border: 1px solid var(--fx-hairline);
    border-radius: var(--fx-radius);
    transition: border-color 0.2s, color 0.2s, background-color 0.2s;
}

.menu_button:hover {
    border-color: var(--fx-accent);
    color: var(--fx-accent);
}

.menu_button.menu_button_default {
    box-shadow: none;
}

/* 确认框的「确定」：默认暗红底 → 强调色实底 */
.menu_button.popup-button-ok,
#dialogue_popup_ok,
#dialogue_del_mes_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual {
    background-color: var(--fx-accent);
    border-color: var(--fx-accent);
    color: var(--fx-on-accent);
}

.menu_button.popup-button-ok:hover,
#dialogue_popup_ok:hover,
#dialogue_del_mes_ok:hover,
#bulk_tag_popup_reset:hover,
#bulk_tag_popup_remove_mutual:hover {
    background-color: color-mix(in srgb, var(--fx-accent) 82%, var(--fx-ink));
    color: var(--fx-on-accent);
}

/* 收藏、角色世界书、聊天世界书亮起时：强调色实底，一眼可见 */
.fav_on,
.world_set,
.toggleEnabled {
    color: var(--fx-accent) !important;
}

.menu_button.fav_on,
.menu_button.world_set {
    background-color: var(--fx-accent);
    border-color: var(--fx-accent);
    color: var(--fx-on-accent) !important;
}

.menu_button.fav_on:hover,
.menu_button.world_set:hover {
    background-color: color-mix(in srgb, var(--fx-accent) 82%, var(--fx-ink));
    color: var(--fx-on-accent) !important;
}

/* 删除按钮：平时只是灰图标，悬停才变实心警示 */
.menu_button.red_button,
.menu_button.redWarningBG {
    background-color: transparent !important;
    color: var(--fx-meta);
}

.menu_button.red_button:hover,
.menu_button.redWarningBG:hover {
    background-color: var(--fx-accent) !important;
    border-color: var(--fx-accent);
    color: var(--fx-on-accent);
}

/* ---- 左下「≡」菜单和魔杖菜单：默认半透明 ---- */
.options-content a,
.list-group-item {
    opacity: 1;
    color: var(--fx-meta);
    transition: color 0.2s;
}

.options-content a:hover,
.list-group-item:hover,
#extensionsMenu > div:hover,
#extensionsMenu > .extension_container > div:hover {
    color: var(--fx-ink);
}

/* ---- 两侧贴边的面板：默认高度是「屏幕 − 顶栏」，底部空出一条缝 ---- */
.fillLeft,
.fillRight {
    max-height: 100vh;
    max-height: 100dvh;
}

/* ---- 多选列表（手机端「已启用世界书」）：默认每个 option 都是黑块 ---- */
select[multiple] option:not(:checked) {
    background-color: transparent;
    color: var(--fx-ink);
}

select[multiple] option:checked,
select[multiple]:focus option:checked {
    background: linear-gradient(color-mix(in srgb, var(--fx-accent) 24%, transparent), color-mix(in srgb, var(--fx-accent) 24%, transparent));
    color: var(--fx-ink);
}

/* ---- 标签与筛选圆钮：行内色块 → 细线 ---- */
#rm_print_characters_block .tag,
.tags .tag {
    border-color: var(--fx-hairline) !important;
    background-color: transparent !important;
    color: var(--fx-meta) !important;
    opacity: 1;
}

.rm_tag_filter .tag.actionable {
    background-color: transparent !important;
    border: 1px solid var(--fx-hairline) !important;
    color: var(--fx-meta) !important;
    filter: none;
    opacity: 1;
}

.rm_tag_filter .tag.actionable.selected {
    border-color: var(--fx-accent) !important;
    color: var(--fx-accent) !important;
}

/* 当前聊天角色 / 默认人设：不用绿色、金色 */
.avatar.is_active,
.group_member.is_active {
    outline: 1px solid var(--fx-accent);
    outline-offset: 2px;
}

.avatar-container.default_persona .avatar {
    outline-color: var(--fx-accent);
}

.ch_fav_icon {
    color: var(--fx-accent);
}

/* ---- 表单 ---- */
.text_pole,
select,
.select2-container .select2-selection {
    background-color: var(--fx-surface);
    border: 1px solid var(--fx-hairline);
    border-radius: var(--fx-radius);
}

.text_pole:focus,
select:focus {
    border-color: color-mix(in srgb, var(--fx-accent) 70%, transparent);
    outline: none;
}

input[type='checkbox'] {
    border-radius: var(--fx-radius);
    border: 1px solid var(--fx-meta);
    outline: 0;
    background-color: transparent;
    box-shadow: none;
    filter: none;
}

input[type='checkbox']:checked {
    border-color: var(--fx-accent);
    background-color: var(--fx-accent);
}

input[type='checkbox']::before {
    box-shadow: inset 1em 1em var(--fx-on-accent);
}

.neo-range-slider {
    height: 2px !important;
    margin-top: 10px !important;
    border-radius: 0 !important;
    background: color-mix(in srgb, var(--fx-ink) 30%, transparent) !important;
    box-shadow: none !important;
}

/* 展开图标：实心圆圈太重，换成细箭头 */
.inline-drawer-icon {
    font-size: var(--mainFontSize);
    color: var(--fx-meta);
    filter: none;
}

.inline-drawer-icon.fa-circle-chevron-down::before {
    content: '\f078';
}

.inline-drawer-icon.fa-circle-chevron-up::before {
    content: '\f077';
}

/* 多选删除消息时的选中底色：默认暗红 */
#chat .mes.selected {
    background-color: color-mix(in srgb, var(--fx-accent) 12%, transparent);
}

/* 系统通知 */
#toast-container > .toast {
    background-color: var(--SmartThemeBlurTintColor) !important;
    background-image: none;
    border: 1px solid var(--fx-hairline);
    border-left: 3px solid var(--fx-meta);
    border-radius: var(--fx-radius);
    box-shadow: 0 12px 32px var(--SmartThemeShadowColor);
    color: var(--fx-ink);
    opacity: 1;
}

#toast-container > .toast-warning,
#toast-container > .toast-error {
    border-left-color: var(--fx-accent);
}

::selection {
    background-color: color-mix(in srgb, var(--fx-accent) 26%, transparent);
}
/* ==== end shared/st-fixes.css ==== */

/* ---------- 正文中文：先找设备上装的 MiSans（不下载），没有就落到下一个字体（思源黑体） ----------
 * MiSans 的粗细名不按常规：Medium 是 380（用户选的正文），Semibold 是 520（加粗） */
@font-face {
    font-family: 'XY MiSans';
    font-weight: 100 549;
    src: local('MiSans Medium'), local('MiSans-Medium');
}

@font-face {
    font-family: 'XY MiSans';
    font-weight: 550 1000;
    src: local('MiSans Semibold'), local('MiSans-Semibold');
}

/* ---------- 内部变量（想改的都在最上方的可改区，这里不用动） ---------- */
:root {
    --xy-paper: var(--SmartThemeChatTintColor);
    --xy-panel: var(--SmartThemeBlurTintColor);
    --xy-text: var(--SmartThemeBodyColor);
    --xy-em: var(--SmartThemeEmColor);
    --xy-head: var(--SmartThemeQuoteColor);
    --xy-line: var(--SmartThemeBorderColor);
    --xy-accent: var(--SmartThemeUnderlineColor);
    --xy-dim: color-mix(in srgb, var(--xy-text) 70%, transparent);   /* 灰字 = 字色 70%（Wispr 用 50%，不够 4.5:1） */
    --xy-card: color-mix(in srgb, var(--xy-text) 8%, transparent);    /* 卡片、输入框 */
    --xy-chip: #02403A;                                               /* 彩色名字下面垫的底 */
    --xy-label: var(--xy-night-label);
    --xy-code-bg: var(--xy-night-code);
    --xy-code-ink: #FFFFEB;
    --xy-sub-bg: var(--xy-text);       /* 对白字幕条：反色 */
    --xy-sub-fg: var(--xy-paper);
    --xy-on-accent: #1A1A1A;
    --xy-char-t: var(--xy-char-t-night);
    --xy-you-t: var(--xy-you-t-night);
    --xy-is-day: 0;

    --xy-measure-w: calc(var(--xy-measure) * var(--xy-read-size));

    /* 接到公共片段 */
    --fx-ink: var(--xy-text);
    --fx-meta: var(--xy-dim);
    --fx-accent: var(--xy-accent);
    --fx-on-accent: var(--xy-on-accent);
    --fx-hairline: var(--xy-line);
    --fx-surface: var(--xy-card);
    --fx-radius: 14px;
    --fx-mes-buttons-idle: var(--xy-mes-buttons-idle);

    /* 世界书 / 预设：开 = 橘红竖条，关 = 浅竖轨（标题照常可读）。第二阶段换成 Wispr 那种竖轨 + 药丸 */
    --st-entry-bar: 5px;
    --st-entry-on: var(--xy-accent);
    --st-entry-constant: var(--xy-label);
    --st-entry-off: var(--xy-card);
    --st-entry-off-style: solid;
    --st-entry-off-bg: none;
    --st-entry-off-title-color: var(--xy-text);
    --st-entry-off-title-style: normal;
    --st-entry-radius: 14px;

    --mainFontFamily: var(--xy-sans);
    --monoFontFamily: var(--xy-code-font);
}

body {
    font-family: var(--xy-sans);
    font-weight: 500;
    -webkit-font-smoothing: antialiased;
}

/* ================================================================
 * 纸
 * ================================================================ */
#bg1::after {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--xy-paper);
    pointer-events: none;
}

#chat {
    background-color: var(--xy-paper);
    backdrop-filter: none;
    --avatar-base-width: var(--xy-avatar);
    --avatar-base-height: var(--xy-avatar);
    --avatar-base-border-radius-round: 50%;
}

#top-bar,
#top-settings-holder {
    background-color: var(--xy-paper);
    backdrop-filter: none;
    border-bottom: 1px solid var(--xy-line);
    box-shadow: none;
}

/* 面板：大圆角卡片，一道细线，柔和的影子 */
.drawer-content,
#left-nav-panel,
#right-nav-panel,
.popup {
    background-color: var(--xy-panel);
    backdrop-filter: none;
    border: 1px solid var(--xy-line);
    border-radius: var(--xy-radius);
    box-shadow: 0 18px 48px -12px var(--SmartThemeShadowColor);
}

/* ================================================================
 * 消息
 * ================================================================ */
#chat .mes {
    --xy-pc: var(--xy-char-c);
    --xy-pi: var(--xy-char-ink);
    --xy-pt: var(--xy-char-t);
    padding: var(--xy-pad-top) var(--xy-pad-right) var(--xy-pad-bottom) var(--xy-pad-left);
    border: 0;
    border-radius: 0;
    background: transparent;
}

#chat .mes[is_user='true'] {
    --xy-pc: var(--xy-you-c);
    --xy-pi: var(--xy-you-ink);
    --xy-pt: var(--xy-you-t);
}

/* 旁白、系统消息：不分人，用压一档的奶油 */
#chat .mes[is_system='true'] {
    --xy-pc: var(--xy-card);
    --xy-pi: var(--xy-text);
    --xy-pt: var(--xy-text);
}

/* ---- 名字：默认放在消息上方的胶囊里（声波小图标 + 名字），头像不显示 ---- */
#chat .mes .mesAvatarWrapper {
    display: none;
}

#chat .mes .ch_name {
    margin-bottom: 8px;
}

#chat .mes .ch_name .name_text {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 3px 11px 3px 9px;
    border-radius: 999px;
    background: var(--xy-pc);
    color: var(--xy-pi);
    font-family: var(--xy-sans-bold);
    font-size: calc(var(--mainFontSize) * 0.8);
    font-weight: 600;
    line-height: 1.4;
    letter-spacing: 0.02em;
}

/* 声波：四根圆头短竖条 */
#chat .mes .ch_name .name_text::before {
    content: '';
    flex: none;
    width: 13px;
    height: 9px;
    background: currentColor;
    -webkit-mask: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 13 9'><rect x='0' y='3' width='2' height='3' rx='1'/><rect x='3.6' y='1' width='2' height='7' rx='1'/><rect x='7.2' y='0' width='2' height='9' rx='1'/><rect x='10.8' y='2.5' width='2' height='4' rx='1'/></svg>") center / contain no-repeat;
    mask: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 13 9'><rect x='0' y='3' width='2' height='3' rx='1'/><rect x='3.6' y='1' width='2' height='7' rx='1'/><rect x='7.2' y='0' width='2' height='9' rx='1'/><rect x='10.8' y='2.5' width='2' height='4' rx='1'/></svg>") center / contain no-repeat;
}

/* 彩色名字：去掉声波，名字本身上色，底下垫一层灰（浅色名字直接写在纸上看不清，所以用够深 / 够浅的那一档） */
@container style(--xy-name: text) {
    #chat .mes .ch_name .name_text {
        padding: 3px 10px;
        background: var(--xy-chip);
        color: var(--xy-pt);
    }

    #chat .mes .ch_name .name_text::before {
        content: none;
    }
}

/* 圆头像：头像回来，名字不加底 */
@container style(--xy-name: avatar) {
    #chat .mes .mesAvatarWrapper {
        display: flex;
        margin-right: 14px;
    }

    #chat .mes .ch_name .name_text {
        padding: 0;
        background: none;
        color: var(--xy-head);
        font-size: calc(var(--mainFontSize) * 0.94);
    }

    #chat .mes .ch_name .name_text::before {
        content: none;
    }
}

#chat .mes .avatar img {
    border-radius: 50%;
}

/* 时间、编号：等宽小标签 */
#chat .mes .timestamp,
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay,
#chat .mes .mesIDDisplay {
    font-family: var(--xy-label-font);
    font-size: calc(var(--mainFontSize) * 0.74);
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.02em;
    color: var(--xy-dim);
    opacity: 1;
}

#chat .mes .timestamp {
    margin-left: 10px;
}

/* ---- 正文 ---- */
#chat .mes_text {
    max-width: var(--xy-measure-w);
    font-family: var(--xy-sans);
    font-size: var(--xy-read-size);
    font-weight: var(--xy-read-weight);
    color: var(--xy-text);
    text-autospace: normal;
}

#chat .mes_text:has(.TH-render, iframe, .edit_textarea) {
    max-width: none;
}

@supports not (hanging-punctuation: first) {
    #chat .mes_text p {
        text-wrap: pretty;
    }
}

/* 你的话：放进气泡，左下角近乎直角（像从这一边说出来的），宽度跟着字走。--xy-bubble 设 0 关闭 */
@container style(--xy-bubble: 1) {
    #chat .mes[is_user='true'] .mes_text:not(:has(.edit_textarea)) {
        width: fit-content;
        padding: 12px 18px !important;
        border-radius: 20px 20px 20px 6px;
        background: var(--xy-pc);
        color: var(--xy-pi);
        --xy-em: color-mix(in srgb, var(--xy-pi) 70%, transparent);
        --xy-sub-bg: var(--xy-pi);
        --xy-sub-fg: var(--xy-pc);
    }
}

/* 对白（q）：字幕条——反色的一条底，加粗。换行时每行各自带圆角 */
#chat .mes_text q {
    padding: 2px 7px;
    border-radius: 6px;
    background: var(--xy-sub-bg);
    color: var(--xy-sub-fg);
    font-family: var(--xy-sans-bold);
    font-weight: 600;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
}

/* 心理（单星号 = em）：中文没有斜体，换成楷体（汇文正楷）；西文是 Garamond 斜体。淡一档 */
#chat .mes_text em,
#chat .mes_text i:not([class*='fa-']) {
    font-family: var(--xy-em-font);
    font-style: italic;
    font-synthesis: none;
    font-weight: 400;
    font-size: 1.04em;
    color: var(--xy-em);
}

#chat .mes_text q em,
#chat .mes_text q i:not([class*='fa-']) {
    color: inherit;
}

#chat .mes_text strong {
    font-family: var(--xy-sans-bold);
    font-weight: 700;
    color: var(--xy-head);
}

#chat .mes_text u {
    text-decoration-color: var(--xy-accent);
    text-decoration-thickness: 2px;
    text-underline-offset: 0.28em;
}

#chat .mes_text a {
    color: var(--xy-head);
    text-decoration: underline 1.5px var(--xy-accent);
    text-underline-offset: 0.25em;
}

/* 正文里的标题：大字（Garamond + 思源宋体，中文缩小一点） */
#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    margin: 1.2em 0 0.45em;
    font-family: var(--xy-display);
    font-weight: 400;
    line-height: 1.2;
    letter-spacing: -0.01em;
    color: var(--xy-head);
}

#chat .mes_text h1 {
    font-size: 1.75em;
}

#chat .mes_text h2 {
    font-size: 1.4em;
}

#chat .mes_text :is(h3, h4, h5, h6) {
    font-size: 1.15em;
}

/* 引用块：左边一根竖轨（和开关条同一种轨道） */
#chat .mes_text blockquote {
    margin: 1em 0;
    padding: 0.1em 0 0.1em 1em;
    border: 0;
    border-left: 5px solid var(--xy-card);
    border-radius: 0;
    background: none;
    color: var(--xy-text);
}

#chat .mes_text hr {
    height: 0;
    margin: 1.5em 0;
    border: 0;
    border-top: 1px solid var(--xy-line);
    background: none;
}

/* 单行代码：压一档的奶油底 */
#chat .mes_text :not(pre) > code {
    padding: 0.12em 0.45em;
    border: 0;
    border-radius: 6px;
    background: var(--xy-card);
    font-family: var(--xy-code-font);
    font-size: 0.88em;
    font-weight: 400;
    color: var(--xy-text);
}

/* 代码块：深色底（昼深绿 / 夜墨）、奶油字，大圆角 */
#chat .mes_text pre {
    margin: 1em 0;
    padding: 1em 1.2em;
    border: 0;
    border-radius: 18px;
    background: var(--xy-code-bg);
}

#chat .mes_text pre code,
#chat .mes_text pre code.hljs {
    padding: 0;
    border: 0;
    background: transparent;
    font-family: var(--xy-code-font);
    font-size: 0.86em;
    font-weight: 400;
    line-height: 1.7;
    color: var(--xy-code-ink);
}

/* 没单独配色的高亮一律回到奶油字（酒馆自带的高亮配色在深底上有的看不清，如 console、this） */
#chat .mes_text pre [class*='hljs-'] {
    color: var(--xy-code-ink);
}

#chat .mes_text pre :is(.hljs-keyword, .hljs-built_in, .hljs-literal, .hljs-variable.language_) {
    color: #FFA946;
}

#chat .mes_text pre :is(.hljs-string, .hljs-number, .hljs-attr, .hljs-property) {
    color: #FFBCF2;
}

#chat .mes_text pre :is(.hljs-title, .hljs-name) {
    color: #F0D7FF;
}

#chat .mes_text pre .hljs-comment {
    color: rgba(255, 255, 235, 0.7);
    font-style: normal;
}

/* 折叠块：一颗胶囊，点开后内容挂在竖轨右边 */
#chat .mes_text details {
    margin: 0.6em 0;
    padding: 0;
    border: 0;
}

#chat .mes_text summary {
    display: inline-flex;
    align-items: center;
    gap: 0.5em;
    padding: 0.25em 0.9em 0.25em 0.7em;
    border-radius: 999px;
    list-style: none;
    background: var(--xy-card);
    cursor: pointer;
    font-family: var(--xy-sans-bold);
    font-size: 0.88em;
    font-weight: 600;
    color: var(--xy-text);
}

#chat .mes_text summary::-webkit-details-marker {
    display: none;
}

#chat .mes_text summary::before {
    content: '';
    width: 0.45em;
    height: 0.45em;
    border-right: 1.5px solid currentColor;
    border-bottom: 1.5px solid currentColor;
    transform: rotate(-45deg);
    transition: transform 0.2s;
}

#chat .mes_text details[open] > summary::before {
    transform: rotate(45deg);
}

#chat .mes_text details[open] > :not(summary) {
    margin-left: 0.3em;
    padding-left: 0.9em;
    border-left: 5px solid var(--xy-card);
}

#chat .mes_text li::marker {
    color: var(--xy-dim);
}

/* ---- 思维链：小字，左边一根竖轨 ---- */
#chat .mes_reasoning_header {
    margin: 0.2em 0 0.5em;
    padding: 3px calc(1.2em + 10px) 3px 10px;
    border: 0;
    border-radius: 999px;
    background: var(--xy-card);
    font-family: var(--xy-label-font);
    font-size: calc(var(--mainFontSize) * 0.74);
    font-weight: 700;
    color: var(--xy-text);
}

#chat .mes_reasoning_details .mes_reasoning_arrow {
    right: 10px;
    font-size: calc(var(--mainFontSize) * 0.6);
    color: inherit;
}

#chat .mes_reasoning {
    max-width: var(--xy-measure-w);
    margin: 0 0 0.9em 2px;
    padding: 0 0 0 1em;
    border: 0;
    border-left: 5px solid var(--xy-card);
    border-radius: 0;
    font-size: calc(var(--mainFontSize) * 0.9);
    line-height: 1.8;
    color: var(--xy-dim);
}

/* 还在想：标题后面一颗橘红小药丸慢慢呼吸 */
#chat .mes_reasoning_details[data-state='thinking'] .mes_reasoning_header_title::after {
    content: '';
    display: inline-block;
    width: 1.1em;
    height: 0.42em;
    margin-left: 0.6em;
    border-radius: 999px;
    background: var(--xy-accent);
    vertical-align: 0.1em;
    animation: xy-breathe 1.6s ease-in-out infinite;
}

@keyframes xy-breathe {
    50% { opacity: 0.35; transform: scaleX(0.7); }
}

/* ---- 翻页 ---- */
/* 酒馆把左右箭头叠在最后一条消息的左下角，会压住最后一行字；先留出一行的空（第二阶段换成键帽） */
#chat .mes.last_mes:has(.swipe_left:not([style*='none'])) .mes_block {
    padding-bottom: calc(var(--mainFontSize) * 2.2);
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipeRightBlock {
    color: var(--xy-dim);
    opacity: 1;
}

#chat .swipes-counter {
    font-family: var(--xy-label-font);
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    color: var(--xy-dim);
    opacity: 1;
}

#chat .last_mes .swipes-counter {
    opacity: 1 !important;
}

/* 编辑消息 */
#chat .mes .edit_textarea {
    font-family: var(--xy-sans);
    font-size: var(--xy-read-size);
    line-height: var(--st-mes-line-height);
    background-color: var(--xy-card);
    border: 1px solid var(--xy-line);
    border-radius: 14px;
}

.tags.tags_inline,
.ch_additional_info,
#rm_print_characters_block .tag,
.tags .tag .tag_name {
    opacity: 1;
    color: var(--xy-dim);
}

/* ================================================================
 * 输入区：Wispr 那种输入卡片——一道细线、圆角 14
 * ================================================================ */
#form_sheld {
    padding: 8px 10px 10px;
    background-color: var(--xy-paper);
}

/* 外层只当容器：快速回复（QR）按钮排在上面，卡片只框住输入这一行 */
#send_form {
    border: 0;
    border-radius: 0;
    background: transparent;
    backdrop-filter: none;
    overflow: visible;
}

#nonQRFormItems {
    box-sizing: border-box;
    border: 1px solid color-mix(in srgb, var(--xy-text) 25%, transparent);
    border-radius: 14px;
    background: var(--xy-panel);
    transition: border-color 0.2s;
}

#send_form:has(#send_textarea:focus-visible) {
    outline: none;
}

#send_form:has(#send_textarea:focus-visible) #nonQRFormItems {
    border-color: var(--xy-text);
}

#send_textarea {
    background: transparent;
    border: 0;
    font-family: var(--xy-sans);
    font-weight: 500;
    color: var(--xy-text);
}

#send_textarea:focus {
    outline: none;
}

#send_textarea::placeholder {
    color: var(--xy-dim);
}

@supports (-webkit-touch-callout: none) {
    @media (max-width: 1000px) {
        #send_textarea {
            font-size: max(16px, var(--mainFontSize));
        }
    }
}

#leftSendForm > div,
#rightSendForm > div {
    opacity: 1;
    filter: none;
    color: var(--xy-dim);
    transition: color 0.2s;
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--xy-text);
}

/* 发送：橘红 */
#send_but {
    color: var(--xy-accent) !important;
}

#top-settings-holder #API-status-top.redOverlayGlow {
    color: var(--xy-accent);
    opacity: 1 !important;
}

.regex_script_name {
    min-width: 0;
    white-space: normal;
    overflow-wrap: anywhere;
}

/* ================================================================
 * 界面：图标、按钮、输入框、区块标题
 * ================================================================ */
.drawer-icon {
    position: relative;
    color: var(--xy-dim);
    opacity: 1;
    filter: none;
    transition: color 0.2s;
}

.drawer-icon:hover,
.drawer-icon.openIcon {
    color: var(--xy-text);
}

/* 打开的那一个：下面一颗橘红小药丸（和开关条同一种记号） */
.drawer-icon.openIcon::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -9px;
    width: 18px;
    height: 4px;
    margin-left: -9px;
    border-radius: 999px;
    background: var(--xy-accent);
}

/* 按钮：胶囊 */
.menu_button,
.menu_button_icon {
    border: 0;
    border-radius: 999px;
    background-color: var(--xy-card);
    color: var(--xy-text);
    font-family: var(--xy-sans-bold);
    font-weight: 600;
    opacity: 1;
    filter: none;
    transition: background-color 0.2s;
}

.menu_button:hover,
.menu_button_icon:hover {
    background-color: color-mix(in srgb, var(--xy-text) 16%, transparent);
}

/* 输入框、下拉框 */
.text_pole,
select,
textarea:not(#send_textarea) {
    border: 1px solid transparent;
    border-radius: 12px;
    background-color: var(--xy-card);
    color: var(--xy-text);
}

.text_pole:focus,
select:focus,
textarea:not(#send_textarea):focus {
    border-color: var(--xy-text);
    outline: none;
}

/* 区块标题：等宽小标签（昼深绿 / 夜杏黄），下面一道细线 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background: transparent;
    border: 0;
    border-bottom: 1px solid var(--xy-line);
    border-radius: 0;
    font-weight: 600;
}

#user-settings-block h4,
.standoutHeader {
    font-family: var(--xy-label-font);
    font-weight: 700;
    letter-spacing: 0.04em;
    color: var(--xy-label);
}

/* 滑块：粗轨道 + 橘红小药丸 */
input[type='range'] {
    height: 5px;
    border: 0;
    border-radius: 999px;
    background: var(--xy-card);
    box-shadow: none;
    filter: none;
}

input[type='range']:hover,
.neo-range-slider:hover {
    filter: none;
}

input[type='range']::-webkit-slider-thumb {
    width: 22px;
    height: 12px;
    border: 0;
    border-radius: 999px;
    background: var(--xy-accent);
    box-shadow: 0 0 0 2px var(--xy-panel);
}

/* 勾选框：开着是橘红 */
input[type='checkbox']:checked {
    background-color: var(--xy-accent);
}

/* 酒馆写死的半透明小字：预设头部的「总词符数」（白 50%）、群组的「在此群组中」（灰 70%） */
#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--xy-dim);
}

#rm_print_characters_block .character_name_block_sub_line {
    color: var(--xy-text);
    opacity: 1;
}

#rm_print_characters_block .ch_name {
    color: var(--xy-text);
}

/* ---------- 角色面板 ---------- */
#rm_button_selected_ch {
    opacity: 1;
}

#rm_button_selected_ch h2 {
    font-family: var(--xy-display);
    font-weight: 400;
    color: var(--xy-head);
}

/* 弹窗 */
.popup {
    color: var(--xy-text);
}

.popup .popup-button-ok {
    background-color: var(--xy-text);
    color: var(--xy-paper);
}

/* 提示条 */
#toast-container > div {
    border-radius: 14px;
    opacity: 1;
    box-shadow: 0 12px 32px -10px var(--SmartThemeShadowColor);
}
/* ==== end themes/xuyu/base.css ==== */
/* ==== themes/xuyu/controls.css ==== */
/* ================================================================
 * 絮语 · 开关条与键帽（阶段 2）
 *
 * 开关条（Wispr 首页「Speak naturally / Edits as you speak / Use it anywhere」那排选项卡）：
 *   左边一根 5px 的浅色竖轨，开着的那一行亮一颗橘红小药丸（从中间长出来）。
 *   关着的标题是字色 70%，照样看得清。用在预设条目、世界书条目、聊天记录列表。
 *
 * 键帽（Wispr 样式表里叫 key-style，画快捷键用的）：1px 描边 + 正下方 2px 不带模糊的硬阴影，
 *   按下去阴影收掉、键往下沉 2px。只给真的能按的小按钮：快速回复、翻页箭头、弹窗按钮、快捷键提示。
 * ================================================================ */
:root {
    --xy-rail: var(--xy-card);         /* 竖轨 */
    --xy-key-bg: var(--xy-panel);
    --xy-key-line: rgba(255, 255, 235, 0.5);
    --xy-key-sh: #01231F;
    --xy-ease: cubic-bezier(0.3, 0.7, 0.3, 1);

    /* 公共片段的左边框不要了，换成下面的竖轨 */
    --st-entry-bar: 0px;
    --st-entry-off: transparent;
}

/* ---------------- 开关条：预设 ---------------- */
/* 竖轨：画在整个列表上，一整根，两头是圆的（条目之间有缝，逐条画会断开） */
#completion_prompt_manager #completion_prompt_manager_list,
#world_popup_entries_list,
#select_chat_div {
    position: relative;
    padding-inline-start: 0;
    background: none;
}

#completion_prompt_manager #completion_prompt_manager_list::before,
#world_popup_entries_list::before,
#select_chat_div::before {
    content: '';
    position: absolute;
    left: 4px;
    top: 0;
    bottom: 0;
    width: 5px;
    border-radius: 999px;
    background: var(--xy-rail);
    pointer-events: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    position: relative;
    margin: 0;
    padding: 0.55em 0.5em 0.55em 22px;
    border: 0;
    border-radius: 0;
    background: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt::after {
    content: '';
    position: absolute;
    left: 4px;
    width: 5px;
    pointer-events: none;
}

/* 药丸：开着时从中间长出来 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt::after {
    top: 7px;
    bottom: 7px;
    border-radius: 999px;
    background: var(--xy-accent);
    transform: scaleY(1);
    transition: transform 0.3s var(--xy-ease);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled::after {
    transform: scaleY(0);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    background: color-mix(in srgb, var(--xy-text) 5%, transparent);
    border-radius: 0 12px 12px 0;
}

/* 关着的：标题字色 70%，不斜、不变灰 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--xy-dim);
    font-style: normal;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--xy-text);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_tokens {
    font-family: var(--xy-label-font);
    font-weight: 700;
    font-size: calc(var(--mainFontSize) * 0.74);
    color: var(--xy-dim);
}

/* 开关图标：开 = 字色，关 = 字色 70%（亮的已经是药丸了，图标不再抢） */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--xy-text);
    opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action {
    color: var(--xy-dim);
    opacity: 1;
}

/* ---------------- 开关条：世界书 ---------------- */
#world_popup_entries_list .world_entry {
    position: relative;
    margin: 0;
    padding-left: 18px;
    border: 0;
    border-radius: 0;
    background: none;
}

#world_popup_entries_list .world_entry.disabledWIEntry,
#world_popup_entries_list .world_entry.disabledWIEntry:hover {
    opacity: 1;
    filter: none;
    background: none;
}

#world_popup_entries_list .world_entry::after {
    content: '';
    position: absolute;
    left: 4px;
    width: 5px;
    pointer-events: none;
}

/* 药丸只占标题那一行（条目展开后不跟着拉长） */
#world_popup_entries_list .world_entry::after {
    top: 8px;
    height: 24px;
    border-radius: 999px;
    background: var(--xy-accent);
    transition: transform 0.3s var(--xy-ease), background-color 0.3s;
}

#world_popup_entries_list .world_entry.disabledWIEntry::after {
    transform: scaleY(0);
}

/* 常驻（蓝灯）：药丸换成标签色（昼深绿 / 夜杏黄） */
#world_popup_entries_list .world_entry:not(.disabledWIEntry):has(select[name="entryStateSelector"] option[value="constant"]:checked)::after {
    background: var(--xy-label);
}

#world_popup_entries_list .world_entry .world_entry_form {
    border: 0;
    background: none;
}

#world_popup_entries_list .world_entry.disabledWIEntry textarea[name="comment"] {
    color: var(--xy-dim);
    font-style: normal;
}

#world_popup_entries_list .world_entry .killSwitch,
#world_popup_entries_list .world_entry .killSwitch.fa-toggle-on {
    color: var(--xy-text);
    opacity: 1;
}

#world_popup_entries_list .world_entry .killSwitch.fa-toggle-off {
    color: var(--xy-dim);
    opacity: 1;
}

/* ---------------- 开关条：聊天记录列表（只能选一个，当前这条亮药丸） ---------------- */
#select_chat_div .select_chat_block_wrapper {
    position: relative;
    padding-left: 18px;
}

#select_chat_div .select_chat_block_wrapper::after {
    content: '';
    position: absolute;
    left: 4px;
    width: 5px;
    pointer-events: none;
}

#select_chat_div .select_chat_block_wrapper::after {
    top: 12px;
    bottom: 12px;
    border-radius: 999px;
    background: var(--xy-accent);
    transform: scaleY(0);
    transition: transform 0.45s var(--xy-ease);
}

#select_chat_div .select_chat_block_wrapper:has(.select_chat_block[highlight])::after {
    transform: none;
}

#select_chat_div .select_chat_block {
    margin: 0;
    padding: 8px 12px;
    border: 0;
    border-radius: 14px;
    background: none;
    color: var(--xy-dim);
    transition: background-color 0.2s, color 0.3s;
}

#select_chat_div .select_chat_block:hover {
    background: color-mix(in srgb, var(--xy-text) 6%, transparent);
    color: var(--xy-text);
}

#select_chat_div .select_chat_block[highlight] {
    background: none;
    color: var(--xy-text);
}

#select_chat_div .select_chat_block_filename {
    font-family: var(--xy-display);
    font-size: 1.15em;
    color: inherit;
}

#select_chat_div .select_chat_block_filename_item {
    font-family: var(--xy-label-font);
    font-weight: 700;
    font-size: calc(var(--mainFontSize) * 0.74);
    opacity: 1;
    color: var(--xy-dim);
}

/* 当前这条的预览文字像 Wispr 右边的说明一样浮上来 */
@keyframes xy-rise {
    from { opacity: 0; transform: translateY(8px); }
}

#select_chat_div .select_chat_block[highlight] .select_chat_block_mes {
    animation: xy-rise 0.5s 0.06s both;
}

/* ---------------- 键帽 ---------------- */
#qr--bar {
    margin-bottom: 10px;
    padding: 0 2px 2px;
    opacity: 1;
}

#qr--bar > .qr--buttons {
    gap: 8px;
}

:is(#qr--bar > .qr--buttons, #qr--popout > .qr--body > .qr--buttons) .qr--button,
.popup .popup-controls .menu_button,
#chat .swipe_left,
#chat .swipe_right,
kbd {
    border: 1px solid var(--xy-key-line);
    border-radius: 8px;
    background: var(--xy-key-bg);
    color: var(--xy-text);
    box-shadow: 0 2px 0 var(--xy-key-sh);
    opacity: 1;
    filter: none;
    transition: transform 0.06s, box-shadow 0.06s, background-color 0.2s;
}

:is(#qr--bar > .qr--buttons, #qr--popout > .qr--body > .qr--buttons) .qr--button:active,
.popup .popup-controls .menu_button:active,
#chat .swipe_left:active,
#chat .swipe_right:active {
    transform: translateY(2px);
    box-shadow: 0 0 0 var(--xy-key-sh);
}

:is(#qr--bar > .qr--buttons, #qr--popout > .qr--body > .qr--buttons) .qr--button {
    padding: 4px 12px;
    font-family: var(--xy-sans);
    font-weight: 500;
    font-size: calc(var(--mainFontSize) * 0.88);
}

:is(#qr--bar > .qr--buttons, #qr--popout > .qr--body > .qr--buttons) .qr--button:hover,
.popup .popup-controls .menu_button:hover {
    background: var(--xy-card);
}

:is(#qr--bar > .qr--buttons, #qr--popout > .qr--body > .qr--buttons) .qr--button :is(.qr--button-label, .qr--button-expander) {
    color: inherit;
    opacity: 1;
}

/* 弹窗按钮：确定是墨色键（夜版奶油色键），取消是普通键 */
.popup .popup-controls .menu_button {
    min-width: 5em;
    padding: 6px 14px;
    font-family: var(--xy-sans-bold);
    font-weight: 600;
}

.popup .popup-controls .menu_button.popup-button-ok,
.popup .popup-controls .menu_button.popup-button-ok:hover {
    background: var(--xy-text);
    color: var(--xy-paper);
    border-color: var(--xy-text);
}

/* 翻页箭头：两颗小方键 */
#chat .swipe_left,
#chat .swipe_right {
    width: 28px;
    height: 28px;
    display: grid;
    place-items: center;
    padding: 0;
    font-size: 11px;
    color: var(--xy-text);
}

#chat .swipe_left:hover,
#chat .swipe_right:hover {
    background: var(--xy-card);
}

/* 快捷键提示（正文里的 <kbd>、设置里的快捷键说明） */
kbd {
    display: inline-block;
    padding: 0 0.4em;
    border-radius: 6px;
    font-family: var(--xy-label-font);
    font-weight: 700;
    font-size: 0.82em;
    line-height: 1.6;
    vertical-align: 0.08em;
}

/* ---------------- 消息按钮 ---------------- */
#chat .mes .mes_buttons,
#chat .mes .mes_buttons .mes_button,
#chat .mes .extraMesButtons .mes_button {
    color: var(--xy-dim);
    opacity: 1;
    filter: none;
}

#chat .mes .mes_buttons .mes_button:hover {
    color: var(--xy-text);
}

#chat .mes .extraMesButtons {
    gap: 2px;
    padding: 2px 6px;
    border-radius: 999px;
    background: var(--xy-card);
}
/* ==== end themes/xuyu/controls.css ==== */
/* ==== themes/xuyu/icons.css ==== */
/* 絮语：顶栏图标，从「正在播放」那套复制来，线宽改 1.5（Wispr 的细线）。改画法去 themes/nowplaying/icons.css，再跑这段复制 */
/* ================================================================
 * 图标：照播放器的画法重画（24 格、2 像素圆头线条；平时是线，打开时是实心）
 * 每个图标两张：--xy-i-<名> 线条版，--xy-i-<名>-on 实心版。用 mask 画，颜色跟着文字色走
 * ================================================================ */
:root {
    /* 预设（AI 设置）：两根推子 */
    --xy-i-presets: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'><path d='M3.5 7h8.5M18 7h2.5M3.5 17h2.5M12 17h8.5'/><circle cx='15' cy='7' r='2.5'/><circle cx='9' cy='17' r='2.5'/></svg>");
    --xy-i-presets-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black' stroke='black' stroke-width='1.5' stroke-linecap='round'><path d='M3.5 7h8.5M18 7h2.5M3.5 17h2.5M12 17h8.5'/><circle cx='15' cy='7' r='3'/><circle cx='9' cy='17' r='3'/></svg>");
    /* API 连接：插头 */
    --xy-i-api: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path d='M9 3v4M15 3v4M6.5 7h11v3.5a5.5 5.5 0 0 1-11 0zM12 16v5'/></svg>");
    --xy-i-api-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path d='M9 3v4M15 3v4M12 16v5'/><path fill='black' d='M6.5 7h11v3.5a5.5 5.5 0 0 1-11 0z'/></svg>");
    /* 高级格式：Aa */
    --xy-i-format: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path d='M2.5 19 7.5 5l5 14M4.5 14h6'/><circle cx='17.5' cy='15.5' r='3'/><path d='M20.5 12v7'/></svg>");
    --xy-i-format-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'><path d='M2.5 19 7.5 5l5 14M4.5 14h6'/><circle cx='17.5' cy='15.5' r='3'/><path d='M20.5 12v7'/></svg>");
    /* 世界书：一本书 */
    --xy-i-book: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path d='M5 18.5V5a2 2 0 0 1 2-2h12v15H6.5a1.5 1.5 0 0 0 0 3H19'/><path d='M9 7.5h6'/></svg>");
    --xy-i-book-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path fill='black' fill-rule='evenodd' d='M5 18.5V5a2 2 0 0 1 2-2h12v15H6.5A1.5 1.5 0 0 0 5 18.5zM9 6.5a1 1 0 0 0 0 2h6a1 1 0 0 0 0-2z'/><path d='M5 18.5a1.5 1.5 0 0 0 1.5 1.5H19'/></svg>");
    /* 用户设置：齿轮 */
    --xy-i-gear: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black'><circle cx='12' cy='12' r='8.3' stroke-width='3.4' stroke-dasharray='3.26 3.26'/><circle cx='12' cy='12' r='6' stroke-width='1.5'/><circle cx='12' cy='12' r='2.2' stroke-width='1.5'/></svg>");
    --xy-i-gear-on: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black'><circle cx='12' cy='12' r='8.3' stroke-width='3.4' stroke-dasharray='3.26 3.26'/><circle cx='12' cy='12' r='4.6' stroke-width='4.8'/></svg>");
    /* 背景：一幅画 */
    --xy-i-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><rect x='3' y='5' width='18' height='14' rx='2'/><path d='m3.5 17 5-5 3.5 3.5 2.5-2.5 6 5'/><circle cx='16' cy='9.5' r='1.3' fill='black'/></svg>");
