:is(#left-nav-panel, #right-nav-panel, #WorldInfo, #xy_menu, #chat .mes_buttons, .popup) :is(.fa-circle-dot)::before { --xy-ico: var(--xy-u-dot); }
:is(#left-nav-panel, #right-nav-panel, #WorldInfo, #xy_menu, #chat .mes_buttons, .popup) :is(.fa-comment)::before { --xy-ico: var(--xy-u-comment); }
:is(#left-nav-panel, #right-nav-panel, #WorldInfo, #xy_menu, #chat .mes_buttons, .popup) :is(.fa-comment-slash)::before { --xy-ico: var(--xy-u-commentOff); }
:is(#left-nav-panel, #right-nav-panel, #WorldInfo, #xy_menu, #chat .mes_buttons, .popup) :is(.fa-scroll)::before { --xy-ico: var(--xy-u-scroll); }
:is(#left-nav-panel, #right-nav-panel, #WorldInfo, #xy_menu, #chat .mes_buttons, .popup) :is(.fa-window-restore)::before { --xy-ico: var(--xy-u-popout); }
:is(#left-nav-panel, #right-nav-panel, #WorldInfo, #xy_menu, #chat .mes_buttons, .popup) :is(.fa-image-portrait, .fa-id-badge)::before { --xy-ico: var(--xy-u-portrait); }
