/* ==== shared/topinfobar.css ==== */
/* 官方扩展「Chat Top Bar」（https://github.com/SillyTavern/Extension-TopInfoBar）的适配
 * 它在聊天上面插一条 #extensionTopBar：聊天列表侧栏、连接配置、聊天名（下拉切换）、搜索、
 * 聊天管理、新建、改名、删除、关闭；点插头图标再往下展开一条 #extensionConnectionProfiles。
 * 没装这个扩展时这些规则什么也不碰。
 *
 * 扩展的 CSS 是网页载入后才插进 <head> 的，排在主题后面，所以这里都加 html body 提权重。
 * 颜色、尺寸全走下面的 --tib-* 变量（默认取 st-fixes 的 --fx-*），主题在自己的 :root 里改：
 *   --tib-h        条高            --tib-pad     左右内边距        --tib-gap   图标间距
 *   --tib-bg       条底            --tib-line    条下边线          --tib-radius 条圆角
 *   --tib-ink      聊天名、悬停图标  --tib-sub     图标、占位字      --tib-accent 开着的图标、搜索框聚焦
 *   --tib-font     字体            --tib-size    字号              --tib-name-weight 聊天名字重
 *   --tib-btn      图标按钮边长     --tib-btn-radius 按钮圆角        --tib-hover 按钮悬停底
 *   --tib-field-*  搜索框：bg 底 / line 边 / radius 圆角 / h 高
 *   --tib-item-radius  聊天列表侧栏里每一项的圆角
 *   --tib-menu-bg、--tib-menu-ink  下拉菜单里的选项（手机和部分浏览器用系统菜单，管不到）
 *   --tib-mark-bg、--tib-mark-ink  搜索时正文里高亮的字 */
:root {
    --tib-h: 36px;
    --tib-pad: 10px;
    --tib-gap: 6px;
    --tib-bg: transparent;
    --tib-line: var(--fx-hairline, var(--SmartThemeBorderColor));
    --tib-radius: 0;
    --tib-ink: var(--fx-ink, var(--SmartThemeBodyColor));
    --tib-sub: var(--fx-meta, var(--SmartThemeBodyColor));
    --tib-accent: var(--fx-accent, var(--SmartThemeQuoteColor));
    --tib-font: inherit;
    --tib-size: 13px;
    --tib-name-weight: 600;
    --tib-btn: 26px;
    --tib-btn-radius: var(--fx-radius, 0);
    --tib-hover: var(--fx-surface, transparent);
    --tib-field-bg: var(--fx-surface, transparent);
    --tib-field-line: transparent;
    --tib-field-radius: var(--fx-radius, 0);
    --tib-field-h: 24px;
    --tib-item-radius: var(--fx-radius, 0);
    --tib-menu-bg: var(--SmartThemeBlurTintColor);
    --tib-menu-ink: var(--SmartThemeBodyColor);
    --tib-mark-bg: color-mix(in srgb, var(--tib-accent) 32%, transparent);
    --tib-mark-ink: inherit;
}

html body #extensionTopBar,
html body #extensionConnectionProfiles {
    height: var(--tib-h);
    margin: 0;
    padding: 0 var(--tib-pad);
    gap: var(--tib-gap);
    align-items: center;
    align-content: center;
    flex-wrap: nowrap;
    border: 0;
    border-bottom: 1px solid var(--tib-line);
    border-radius: var(--tib-radius);
    background: var(--tib-bg);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: none;
    color: var(--tib-ink);
    font-family: var(--tib-font);
    font-size: var(--tib-size);
}

html body #extensionConnectionProfiles {
    display: none;
}

html body #extensionConnectionProfiles.visible {
    display: flex;
}

/* 图标：实色（酒馆的 .right_menu_button 默认半透明） */
html body #extensionTopBar > .right_menu_button,
html body #extensionConnectionProfiles > i {
    flex: none;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--tib-btn);
    height: var(--tib-btn);
    margin: 0;
    padding: 0;
    border-radius: var(--tib-btn-radius);
    color: var(--tib-sub);
    font-size: 14px;
    opacity: 1;
    filter: none;
    text-shadow: none;
    transition: color .15s, background-color .15s;
}

html body #extensionTopBar > .right_menu_button:hover,
html body #extensionTopBar > .right_menu_button:focus-visible {
    color: var(--tib-ink);
    background-color: var(--tib-hover);
    filter: none;
}

/* 打开着的（聊天列表侧栏、连接配置那一条） */
html body #extensionTopBar > .right_menu_button.active {
    color: var(--tib-accent);
    filter: none;
}

/* 没在聊天里（欢迎页）时灰掉的按钮 */
html body #extensionTopBar > .right_menu_button.not-in-chat {
    opacity: .35;
}

/* 聊天名 / 连接配置：下拉框。扩展用的是一张白色小箭头图，浅色主题看不见，换成跟字同色的两道斜线 */
html body #extensionTopBarChatName,
html body #extensionConnectionProfilesSelect {
    flex: 1 1 auto;
    min-width: 0;
    width: auto;
    height: var(--tib-field-h);
    margin: 0;
    padding: 0 22px 0 4px;
    border: 0;
    border-radius: var(--tib-btn-radius);
    color: var(--tib-ink);
    font: inherit;
    font-weight: var(--tib-name-weight);
    opacity: 1;
    background-color: transparent;
    background-image:
        linear-gradient(45deg, transparent 50%, var(--tib-sub) 50%),
        linear-gradient(135deg, var(--tib-sub) 50%, transparent 50%);
    background-size: 4px 4px;
    background-repeat: no-repeat;
    background-position: calc(100% - 12px) 50%, calc(100% - 8px) 50%;
    box-shadow: none;
    outline: none;
}

html body #extensionTopBarChatName:hover,
html body #extensionConnectionProfilesSelect:hover {
    background-color: var(--tib-hover);
}

html body #extensionTopBarChatName option,
html body #extensionConnectionProfilesSelect option {
    background: var(--tib-menu-bg);
    color: var(--tib-menu-ink);
    font-weight: normal;
}

/* 聊天名只占它要的宽度（最长那个聊天名），搜索框跟在后面，右边一组图标靠右 */
html body #extensionTopBarChatName {
    flex: 0 1 auto;
    max-width: 50%;
}

/* 搜索框 */
html body #extensionTopBarSearchInput {
    flex: 0 1 auto;
    min-width: 0;
    height: var(--tib-field-h);
    min-height: 0;
    margin: 0 auto 0 0;
    padding: 0 8px;
    border: 1px solid var(--tib-field-line);
    border-radius: var(--tib-field-radius);
    background: var(--tib-field-bg);
    color: var(--tib-ink);
    font: inherit;
    font-style: normal;
    opacity: 1;
    box-shadow: none;
    outline: none;
}

html body #extensionTopBarSearchInput:placeholder-shown {
    font-style: normal;
    opacity: 1;
    border-color: var(--tib-field-line);
}

html body #extensionTopBarSearchInput::placeholder {
    color: var(--tib-sub);
    opacity: 1;
}

html body #extensionTopBarSearchInput:focus {
    border-color: var(--tib-accent);
}

/* 放大镜：用渐变画（不写死颜色），一个圈 + 一道斜柄 */
html body #extensionTopBarSearchInput {
    --tib-ico-y: calc((var(--tib-field-h) - 14px) / 2 - 1px);
    padding-left: 26px;
    background-image:
        radial-gradient(circle closest-side, transparent 3.3px, var(--tib-sub) 3.6px 4.7px, transparent 5px),
        linear-gradient(45deg, transparent calc(50% - .8px), var(--tib-sub) calc(50% - .7px) calc(50% + .7px), transparent calc(50% + .8px));
    background-size: 10px 10px, 5px 5px;
    background-position: 9px var(--tib-ico-y), 16px calc(var(--tib-ico-y) + 8px);
    background-repeat: no-repeat;
}

/* 手机：一排塞不下，搜索平时收成一颗放大镜，点开（或里面有字）才展开 */
@media screen and (max-width: 1000px) {
    html body #extensionTopBarSearchInput {
        flex: none;
        width: var(--tib-field-h);
        max-width: none;
        padding: 0 0 0 var(--tib-field-h);
        transition: width .2s;
    }

    html body #extensionTopBarSearchInput:focus,
    html body #extensionTopBarSearchInput:not(:placeholder-shown) {
        width: 42vw;
        padding-right: 8px;
    }

    html body #extensionTopBarSearchInput:placeholder-shown:not(:focus)::placeholder {
        color: transparent;
    }

    html body #extensionTopBarSearchInput {
        background-position: calc(var(--tib-field-h) / 2 - 7px) var(--tib-ico-y), calc(var(--tib-field-h) / 2 + 1px) calc(var(--tib-ico-y) + 8px);
    }
}

html body #extensionConnectionProfilesStatus {
    color: var(--tib-sub);
    opacity: 1;
    font-size: inherit;
}

/* 搜到的字 */
html body #chat mark.highlight {
    background: var(--tib-mark-bg);
    color: var(--tib-mark-ink);
    border-radius: 2px;
}

/* 聊天列表侧栏（浮动小窗，套酒馆自己的 .draggable）：选中、悬停改用主题色 */
html body #extensionSideBar #extensionSideBarContainer .sideBarItem {
    border-color: var(--tib-line);
    border-radius: var(--tib-item-radius);
    font-family: var(--tib-font);
}

html body #extensionSideBar #extensionSideBarContainer .sideBarItem:hover {
    background-color: color-mix(in srgb, var(--tib-ink) 8%, transparent);
}

html body #extensionSideBar #extensionSideBarContainer .sideBarItem.selected {
    background-color: color-mix(in srgb, var(--tib-accent) 20%, transparent);
    border-color: var(--tib-accent);
}
