/* ==== themes/xuyu/topbar.css ==== */
/* ---------------- 官方扩展「Chat Top Bar」：奶油纸上一条细线，开着的按钮下面一颗橘红小药丸 ---------------- */
:root {
    --tib-h: 36px;
    --tib-pad: 14px;
    --tib-gap: 4px;
    --tib-bg: transparent;
    --tib-line: var(--xy-line);
    --tib-ink: var(--xy-text);
    --tib-sub: var(--xy-dim);
    --tib-accent: var(--xy-accent);
    --tib-font: var(--xy-sans-bold);
    --tib-size: 13px;
    --tib-name-weight: 600;
    --tib-btn: 26px;
    --tib-btn-radius: 999px;
    --tib-hover: var(--xy-card);
    --tib-field-bg: var(--xy-card);
    --tib-field-line: transparent;
    --tib-field-radius: 999px;
    --tib-field-h: 24px;
    --tib-menu-bg: var(--xy-panel);
    --tib-menu-ink: var(--xy-text);
    --tib-mark-bg: color-mix(in srgb, var(--xy-accent) 35%, transparent);
