/* ==== themes/xuyu/display.css ==== */
/* ================================================================
 * 絮语 · 大字与照片（阶段 3）
 * 大字只在开头和标题上：欢迎页、启动页、面板标题、角色卡上的名字。
 * 大字 = EB Garamond + 思源宋体（中文缩到 85%），后半句换 Garamond 斜体 + 汇文正楷，
 * 楷体那半句下面一道手画的淡紫线（夜版粉色），从左往右画出来。
 * ================================================================ */
:root {
    /* 手画的线：一条略带起伏的笔触，线宽不跟着拉伸 */
    --xy-ul-day: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 14' preserveAspectRatio='none'><path d='M3 10C38 8.5 70 8 104 5.5 140 3 176 3.5 197 9' fill='none' stroke='%23F0D7FF' stroke-width='4' stroke-linecap='round' vector-effect='non-scaling-stroke'/></svg>");
    --xy-ul-night: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 14' preserveAspectRatio='none'><path d='M3 10C38 8.5 70 8 104 5.5 140 3 176 3.5 197 9' fill='none' stroke='%23FFBCF2' stroke-width='4' stroke-linecap='round' vector-effect='non-scaling-stroke'/></svg>");
    --xy-ul: var(--xy-ul-night);
    /* 照片没装上（没装扩展）时的底：深绿到墨 */
    --xy-photo-fallback: radial-gradient(120% 90% at 85% 10%, #0B6A5E 0%, #034F46 45%, #1A1A1A 100%);
}

@keyframes xy-breathe {
    50% { transform: scaleX(1.9); opacity: 0.55; }
}

@keyframes xy-draw {
    from { background-size: 0% 0.3em; }
    to { background-size: 100% 0.3em; }
}

/* ================================================================
 * 欢迎页：一张照片卡，上面写大字
 * ================================================================ */
#chat > .welcomePanel {
    align-self: stretch;
    min-width: 0;
    width: auto;
    margin: 14px var(--xy-pad-right) 0 var(--xy-pad-left);
    padding: 0;
    gap: 18px;
    background: none;
    border: 0;
}

.welcomePanel .welcomeHeaderLogo {
    display: none;
}

.welcomePanel .welcomeHeaderTitle {
    position: relative;
    isolation: isolate;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-end;
    gap: 0;
    min-height: clamp(260px, 40vh, 460px);
    padding: clamp(22px, 4vw, 44px);
    overflow: hidden;
    border-radius: 36px;
    background: var(--xy-photo, var(--xy-photo-fallback)) center / cover no-repeat, #1A1A1A;
    color: #FFFFEB;
}

/* 照片上压一层暗色，大字才看得清（下深上浅） */
.welcomePanel .welcomeHeaderTitle {
    background:
        linear-gradient(to top, rgba(26, 26, 26, 0.55), rgba(26, 26, 26, 0.05) 70%),
        var(--xy-photo, var(--xy-photo-fallback)) center / cover no-repeat,
        #1A1A1A;
}

.welcomePanel .welcomeHeaderTitle::before,
.welcomePanel .welcomeHeaderTitle::after {
    position: relative;
    max-width: 100%;
    text-wrap: balance;
}

/* 大字 */
.welcomePanel .welcomeHeaderTitle::before {
    content: var(--xy-welcome-big);
    order: 1;
    font-family: var(--xy-display);
    font-weight: 400;
    font-size: clamp(46px, 7.4vw, 92px);
    line-height: 1.12;
    letter-spacing: -0.02em;
    text-shadow: 0 2px 24px rgba(26, 26, 26, 0.35);
}

/* 后半句：斜体（中文楷体），下面一道淡紫线，从左往右画出来 */
.welcomePanel .welcomeHeaderTitle::after {
    content: var(--xy-welcome-alt);
    order: 2;
    margin-top: 0.1em;
    padding-bottom: 0.18em;
    font-family: var(--xy-display-alt);
    font-style: italic;
    font-synthesis: none;
    font-weight: 400;
    font-size: clamp(29px, 4.6vw, 57px);
    line-height: 1.15;
    letter-spacing: -0.01em;
    text-shadow: 0 2px 24px rgba(26, 26, 26, 0.35);
    background: var(--xy-ul-day) left bottom / 100% 0.3em no-repeat;
    animation: xy-draw 0.9s cubic-bezier(0.55, 0, 0.25, 1) 0.4s both;
}

/* 版本号：左上角的等宽小标签 */
.welcomePanel .welcomeHeaderVersionDisplay {
    position: absolute;
    top: clamp(22px, 4vw, 40px);
    left: clamp(22px, 4vw, 44px);
    margin: 0;
    font-family: var(--xy-label-font);
    font-weight: 700;
    font-size: calc(var(--mainFontSize) * 0.78);
    letter-spacing: 0.04em;
    color: rgba(255, 255, 235, 0.85);
    opacity: 1;
}

.welcomePanel .welcomeHeaderTitle > .mes_button {
    position: absolute;
    top: 16px;
    right: 16px;
    z-index: 1;
    color: #FFFFEB;
    opacity: 0.85;
}

/* 最近聊天：大圆角卡片，圆头像，日期用等宽小字 */
.welcomePanel .recentChatsTitle {
    font-family: var(--xy-display);
    font-weight: 400;
    font-size: calc(var(--mainFontSize) * 1.7);
    line-height: 1.2;
    color: var(--xy-head);
}

.welcomeRecent .recentChatList {
    gap: 8px;
}

.welcomeRecent .recentChatList .recentChat {
    border: 0;
    border-radius: 22px;
    padding: 12px 16px;
    background: var(--xy-card);
    transition: background-color 0.2s;
}

.welcomeRecent .recentChatList .recentChat:hover {
    background: color-mix(in srgb, var(--xy-text) 14%, transparent);
}

.welcomeRecent .recentChatList .recentChat .avatar img {
    border-radius: 50%;
}

.welcomeRecent .recentChatList .recentChat .characterName {
    font-family: var(--xy-sans-bold);
    font-weight: 700;
    color: var(--xy-head);
}

.welcomeRecent .recentChatList .recentChat :is(.chatDate, .chatStats) {
    font-family: var(--xy-label-font);
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    color: var(--xy-dim);
    opacity: 1;
}

.welcomeRecent .recentChatList .recentChat .chatMessage {
    color: var(--xy-dim);
    opacity: 1;
}

.welcomePanel .welcomeShortcutsSeparator {
    color: var(--xy-line);
}

/* ================================================================
 * 面板标题、角色卡上的名字：大字
 * ================================================================ */
.drawer-content h3,
#rm_button_selected_ch h2 {
    font-family: var(--xy-display);
    font-weight: 400;
    letter-spacing: -0.01em;
    color: var(--xy-head);
}

.drawer-content h3 {
    font-size: calc(var(--mainFontSize) * 1.6);
    line-height: 1.2;
}

#rm_button_selected_ch h2 {
    font-size: calc(var(--mainFontSize) * 2.1);
    line-height: 1.15;
}

/* ================================================================
 * 启动页：奶油 / 深绿的纸，中间写「絮语」，后半句 Murmur 带下划线；
 * 原来的转圈换成一颗慢慢呼吸的橘红药丸。只在启动时出现（那时页面上还有 #preloader）
 * ================================================================ */
body:has(#preloader) dialog.popup:has(#loader) {
    position: fixed;
    inset: 0;
    width: 100vw !important;
    height: 100dvh !important;
    max-width: none !important;
    max-height: none !important;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    background: var(--xy-paper);
    animation: none;
    overflow: hidden;
}

body:has(#preloader) dialog.popup:has(#loader)::backdrop {
    background-color: var(--xy-paper);
    backdrop-filter: none;
}

body:has(#preloader) dialog.popup:has(#loader) :is(.popup-body, .popup-content) {
    width: 100%;
    height: 100%;
    max-height: none;
    margin: 0;
    padding: 0;
    overflow: visible;
    background: none;
}

body:has(#preloader) #loader,
body:has(#preloader) #loader.splash-screen {
    position: absolute;
    left: 50%;
    top: 46%;
    translate: -50% -50%;
    width: min(90vw, 760px);
    height: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    text-align: center;
    color: var(--xy-head);
    background: none;
}

body:has(#preloader) #loader > :is(.splash-logo, .splash-message) {
    display: none;
}

body:has(#preloader) #loader::before {
    content: var(--xy-splash-big);
    order: 1;
    font-family: var(--xy-display);
    font-weight: 400;
    font-size: clamp(64px, 13vw, 140px);
    line-height: 1.1;
    letter-spacing: -0.02em;
}

body:has(#preloader) #loader::after {
    content: var(--xy-splash-alt);
    order: 2;
    padding-bottom: 0.16em;
    font-family: var(--xy-display-alt);
    font-style: italic;
    font-synthesis: none;
    font-weight: 400;
    font-size: clamp(30px, 5.4vw, 58px);
    line-height: 1.15;
    background: var(--xy-ul) left bottom / 100% 0.3em no-repeat;
    animation: xy-draw 0.9s cubic-bezier(0.55, 0, 0.25, 1) 0.3s both;
}

body:has(#preloader) #loader #load-spinner {
    --spinner-size: auto;
    position: static;
    order: 3;
    width: 34px;
    height: 6px;
    margin-top: 34px;
    translate: none;
    border-radius: 999px;
    background: var(--xy-accent);
    font-size: 0;
    opacity: 1;
    animation: xy-breathe 1.6s ease-in-out infinite;
}

body:has(#preloader) #loader #load-spinner::before {
    content: none;
}

@media (prefers-reduced-motion: reduce) {
    .welcomePanel .welcomeHeaderTitle::after,
    body:has(#preloader) #loader::after,
    body:has(#preloader) #loader #load-spinner {
        animation: none;
    }
}

body.reduced-motion .welcomePanel .welcomeHeaderTitle::after,
body.reduced-motion:has(#preloader) #loader::after,
body.reduced-motion:has(#preloader) #loader #load-spinner {
    animation: none;
}
/* ==== end themes/xuyu/display.css ==== */
/* ==== themes/xuyu/rhythm.css ==== */
/* ================================================================
 * 絮语 · 节奏（打样）
 * Wispr 那种「大标题 / 标题 / 小字跳得很开、留白很大」搬到酒馆：
 *   正文本身保持安静，变化放在正文以外——聊天开头的扉页、面板、模型写出的章节标题和分隔线。
 *
 * 字号只用四档，中间不留含糊的档位：
 *   大标题（扉页角色名、欢迎页）> 标题（面板标题、正文 h1/h2）> 正文 > 等宽小字（标签、时间）
 * ================================================================ */
:root {
    --xy-t-hero: clamp(46px, 5.6vw, 84px);
    --xy-t-title: calc(var(--mainFontSize) * 1.7);
    --xy-t-label: calc(var(--mainFontSize) * 0.74);
    --xy-gap-section: clamp(28px, 4vh, 44px);   /* 区块之间的大留白 */
}

/* ---------------- 扉页：聊天的第一条消息（角色开场白）上方 ---------------- */
/* 往上翻到顶，像翻到一本书的扉页：一行等宽小字（开篇 · 日期）、角色名大字、一道手画线，再空一大段才是开场白 */
#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) {
    padding-top: clamp(56px, 14vh, 140px);
    padding-bottom: calc(var(--xy-pad-bottom) * 2);
}

#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .ch_name {
    margin-bottom: clamp(28px, 5vh, 52px);
    align-items: flex-start;
}

#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .ch_name .alignItemsBaseline {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
}

#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .ch_name .timestamp {
    order: -1;
}

#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .ch_name .name_text {
    display: block;
    width: fit-content;
    padding: 0 0 0.16em;
    border-radius: 0;
    background: var(--xy-ul) left bottom / 100% 0.12em no-repeat;
    color: var(--xy-head);
    font-family: var(--xy-display);
    font-size: var(--xy-t-hero);
    font-weight: 400;
    line-height: 1.08;
    letter-spacing: -0.02em;
    animation: xy-draw-thin 0.9s cubic-bezier(0.55, 0, 0.25, 1) 0.2s both;
}

#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .ch_name .name_text::before {
    content: none;
}

@keyframes xy-draw-thin {
    from { background-size: 0% 0.12em; }
}

/* 名字上方那行小字：一颗角色色的小药丸 + 开篇 · 日期 */
#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .timestamp {
    display: inline-flex !important;
    align-items: center;
    gap: 10px;
    margin: 0;
    color: var(--xy-dim);
}

#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .timestamp::before {
    content: '';
    order: -2;
    width: 22px;
    height: 6px;
    border-radius: 999px;
    background: var(--xy-pc);
}

#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .timestamp::after {
    content: var(--xy-cover-label) ' ·';
    order: -1;
    letter-spacing: 0.08em;
}

/* 开场白没有日期时只写「开篇」 */
#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .timestamp:empty::after {
    content: var(--xy-cover-label);
}

/* 开场白第一段稍大一点，像文章的导语 */
#chat:not(:has(> .welcomePanel)) .mes[mesid='0']:not([is_user='true']) .mes_text > p:first-child {
    font-size: 1.12em;
    line-height: 1.7;
    color: var(--xy-head);
}

/* ---------------- 正文里模型写出来的章节结构 ---------------- */
/* 标题：大的用标题档大字，前面空一大段；小标题用等宽小字，像 Wispr 大标题上面那行标签 */
#chat .mes_text :is(h1, h2) {
    margin: 1.8em 0 0.5em;
    font-size: calc(var(--xy-t-title) * 1.12);
    line-height: 1.15;
}

#chat .mes_text :is(h3, h4, h5, h6) {
    margin: 2em 0 0.7em;
    font-family: var(--xy-label-font);
    font-size: var(--xy-t-label);
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--xy-label);
}

#chat .mes_text > :is(h1, h2, h3, h4, h5, h6):first-child {
    margin-top: 0.2em;
}

/* 分隔线（---）：不画线，空出一大段，段首一颗橘红小药丸——剧情转场时版面跟着停一下 */
#chat .mes_text hr {
    position: relative;
    height: 6px;
    margin: 2.8em 0;
    width: 26px;
    opacity: 1;
    border: 0;
    border-radius: 999px;
    background: var(--xy-accent);
    overflow: visible;
}

/* ---------------- 角色卡面板：大名字 + 等宽小标签 + 大圆角卡片，区块之间空开 ---------------- */
#rm_ch_create_block :is(#creators_notes_div, #description_div, #first_message_div) {
    margin-top: var(--xy-gap-section);
    margin-bottom: 10px;
}

#rm_ch_create_block :is(#creators_notes_div, #description_div, #first_message_div) > .flex-container > span:first-child,
#rm_ch_create_block #creators_notes_div > span:first-child,
#rm_ch_create_block #creators_notes_div h4,
#rm_ch_create_block #creators_notes_div .flex-container > span:first-child {
    font-family: var(--xy-label-font);
    font-size: var(--xy-t-label);
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--xy-label);
}

#rm_ch_create_block :is(#description_textarea, #firstmessage_textarea),
#rm_ch_create_block #spoiler_free_desc .inline-drawer-content {
    padding: 18px 20px;
    border: 0;
    border-radius: 22px;
    background: var(--xy-card);
    font-size: var(--mainFontSize);
    line-height: 1.75;
}

#rm_ch_create_block #avatar_div {
    margin-block: 10px 4px;
}

/* ---------------- 用户设置：区块标题换成标题档大字，区块之间空开 ---------------- */
#user-settings-block h4 {
    margin: var(--xy-gap-section) 0 12px;
    padding-bottom: 8px;
    font-family: var(--xy-display);
    font-size: calc(var(--mainFontSize) * 1.5);
    font-weight: 400;
    letter-spacing: -0.01em;
    color: var(--xy-head);
}

#user-settings-block h4:first-child,
#user-settings-block [name] > h4:first-child {
    margin-top: 6px;
}

#user-settings-block-content {
    column-gap: 36px;
}

#user-settings-block-content .flex-container:has(> label.checkbox_label),
#user-settings-block-content label.checkbox_label {
    row-gap: 10px;
}

#user-settings-block-content label.checkbox_label {
    min-height: 2em;
    align-items: center;
}
/* ==== end themes/xuyu/rhythm.css ==== */
/* ==== themes/xuyu/stage.css ==== */
/* ================================================================
 * 絮语 · 三层底（照 Wispr「Good questions.」那一块）
 * 纸（页面）→ 灰色大圆角底（聊天区）→ 浅色的一层（角色消息的字铺在上面）
 * 夜版同样三层：纸是深绿，聊天区比纸深一档，消息那层比纸浅一档。
 * 你的消息照旧是淡紫气泡，直接放在灰底上。
 * ================================================================ */
:root {
    --xy-stage: var(--xy-night-stage);
    --xy-sheet: var(--xy-night-sheet);
    --xy-chip-stage: #012F2A;          /* 彩色名字垫的底：放在聊天区上要比聊天区再深一档才看得出来 */
    --xy-stage-radius: 32px;
    --xy-stage-gap: 10px;              /* 灰底和顶栏、输入框之间露出来的纸 */
    --xy-ul-day-deep: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 14' preserveAspectRatio='none'><path d='M3 10C38 8.5 70 8 104 5.5 140 3 176 3.5 197 9' fill='none' stroke='%23C69BF0' stroke-width='4' stroke-linecap='round' vector-effect='non-scaling-stroke'/></svg>");
}

@media screen and (max-width: 1000px) {
    :root {
        --xy-stage-radius: 22px;
        --xy-stage-gap: 8px;
    }
}

/* 聊天区：一块灰色大圆角底 */
#chat {
    margin-block: var(--xy-stage-gap);
    border: 0;
    border-radius: var(--xy-stage-radius);
    background-color: var(--xy-stage);
    /* 灰底上的小卡片（消息按钮条、思考块、最近聊天）改用浅色那层，不然和灰底一个颜色 */
    --xy-card: var(--xy-sheet);
    --xy-chip: var(--xy-chip-stage);
}

@media screen and (max-width: 1000px) {
    #chat {
        margin-inline: var(--xy-stage-gap);
    }
}

/* 扉页名字下的手画线：昼版淡紫放在灰底上几乎看不见，深一档 */
:root.dn-day #chat:not(:has(> .welcomePanel)) .mes[mesid='0'] .ch_name .name_text {
    background-image: var(--xy-ul-day-deep);
}

@media (prefers-color-scheme: light) {
    :root:not(.dn-night) #chat:not(:has(> .welcomePanel)) .mes[mesid='0'] .ch_name .name_text {
        background-image: var(--xy-ul-day-deep);
    }
}

/* 角色消息：字铺在浅色那一层上，宽度跟着字走 */
#chat .mes:not([is_user='true']) .mes_text:not(:has(.edit_textarea)) {
    width: fit-content;
    padding: 16px 22px !important;
    border-radius: 20px;
    background: var(--xy-sheet);
}

/* 浅色那层里的小东西（行内代码、引用竖轨、折叠块）反过来用灰底的颜色 */
#chat .mes .mes_text {
    --xy-card: var(--xy-stage);
}

@media screen and (max-width: 1000px) {
    #chat .mes:not([is_user='true']) .mes_text:not(:has(.edit_textarea)) {
        padding: 14px 16px !important;
        border-radius: 18px;
    }
}

/* ---------------- 另一种底：角色消息各一张灰色大圆角卡片，字的那块露出纸色 ----------------
 * 聊天区回到纸色；角色消息整条是一张灰卡片（名字、按钮都在卡片上），正文挖一块露出纸；
 * 你的淡紫气泡直接放在纸上，和角色的灰卡片一深一浅对着。主题设置里切换（--xy-layout: cards） */
@container style(--xy-layout: cards) {
    #chat {
        margin: 0;
        border-radius: 0;
        background-color: var(--xy-paper);
        --xy-card: var(--xy-stage);
    }

    #chat .mes:not([is_user='true']) {
        margin-block: 10px;
        border-radius: var(--xy-radius);
        background: var(--xy-stage);
        --xy-card: var(--xy-sheet);
    }

    #chat .mes:not([is_user='true']) .mes_text:not(:has(.edit_textarea)) {
        background: var(--xy-paper);
    }

    #chat .mes .mes_text {
        --xy-card: var(--xy-stage);
    }
}

@media screen and (max-width: 1000px) {
    @container style(--xy-layout: cards) {
        #chat {
            margin: 0;
        }

        #chat .mes:not([is_user='true']) {
            width: calc(100% - 12px);
            margin-inline: 6px;
        }
    }
}
/* ==== end themes/xuyu/stage.css ==== */

/* ================================================================
 * 昼版（day.css，构建时复制两次，各加一个前缀）
 *   1. 扩展把 <html> 设成 dn-day 时：昼
 *   2. 没装扩展时：跟随系统，系统是浅色模式就是昼（扩展设成 dn-night 时不跟随）
 * ================================================================ */
:root {
    --dn-support: 1;
    --dn-papers: '';
}

/* ==== themes/xuyu/day.css（仅 :root.dn-day） ==== */
:root.dn-day {
    --SmartThemeBodyColor: var(--xy-day-ink) !important;
    --SmartThemeEmColor: var(--xy-day-em) !important;
    --SmartThemeQuoteColor: var(--xy-day-ink) !important;
    --SmartThemeUnderlineColor: var(--xy-flare) !important;
    --SmartThemeBlurTintColor: var(--xy-day-paper) !important;
    --SmartThemeChatTintColor: var(--xy-day-paper) !important;
    --SmartThemeBorderColor: var(--xy-day-line) !important;
    --SmartThemeShadowColor: rgba(26, 26, 26, 0.16) !important;
    --SmartThemeCheckboxTickColor: var(--xy-day-paper);
    --reasoning-body-color: var(--SmartThemeEmColor);
    color-scheme: light;

    --xy-card: var(--xy-day-card);
    --xy-chip: var(--xy-day-card);
    --xy-label: var(--xy-day-label);
    --xy-ul: var(--xy-ul-day);
    --xy-stage: var(--xy-day-stage);
    --xy-sheet: var(--xy-day-sheet);
    --xy-chip-stage: var(--xy-day-sheet);
    --xy-code-bg: var(--xy-day-code);
    --xy-char-t: var(--xy-char-t-day);
    --xy-you-t: var(--xy-you-t-day);
    --xy-is-day: 1;
    --xy-key-bg: var(--xy-day-paper);
    --xy-key-line: rgba(26, 26, 26, 0.5);
    --xy-key-sh: #8C8C82;

    
    --white20a: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
    --white30a: color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);
    --white50a: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, transparent);
    --white60a: color-mix(in srgb, var(--SmartThemeBodyColor) 85%, transparent);
    --white70a: color-mix(in srgb, var(--SmartThemeBodyColor) 90%, transparent);
    --black30a: color-mix(in srgb, var(--SmartThemeBodyColor) 5%, transparent);
    --black50a: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
    --black60a: color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent);
    --black70a: color-mix(in srgb, var(--SmartThemeBodyColor) 12%, transparent);
    --grey30a: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
    --interactable-outline-color: var(--SmartThemeBodyColor);
    --interactable-outline-color-faint: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
}

:root.dn-day #nonQRFormItems {
    background: var(--xy-day-paper);
}

:root.dn-day .drawer-content,
:root.dn-day #left-nav-panel,
:root.dn-day #right-nav-panel,
:root.dn-day .popup {
    box-shadow: 0 18px 48px -14px rgba(26, 26, 26, 0.22);
}
/* ==== end themes/xuyu/day.css ==== */

@media (prefers-color-scheme: light) {
/* ==== themes/xuyu/day.css（仅 :root:not(.dn-night)） ==== */
:root:not(.dn-night) {
    --SmartThemeBodyColor: var(--xy-day-ink) !important;
    --SmartThemeEmColor: var(--xy-day-em) !important;
    --SmartThemeQuoteColor: var(--xy-day-ink) !important;
    --SmartThemeUnderlineColor: var(--xy-flare) !important;
    --SmartThemeBlurTintColor: var(--xy-day-paper) !important;
    --SmartThemeChatTintColor: var(--xy-day-paper) !important;
    --SmartThemeBorderColor: var(--xy-day-line) !important;
    --SmartThemeShadowColor: rgba(26, 26, 26, 0.16) !important;
    --SmartThemeCheckboxTickColor: var(--xy-day-paper);
    --reasoning-body-color: var(--SmartThemeEmColor);
    color-scheme: light;

    --xy-card: var(--xy-day-card);
    --xy-chip: var(--xy-day-card);
    --xy-label: var(--xy-day-label);
    --xy-ul: var(--xy-ul-day);
    --xy-stage: var(--xy-day-stage);
    --xy-sheet: var(--xy-day-sheet);
    --xy-chip-stage: var(--xy-day-sheet);
    --xy-code-bg: var(--xy-day-code);
    --xy-char-t: var(--xy-char-t-day);
    --xy-you-t: var(--xy-you-t-day);
    --xy-is-day: 1;
    --xy-key-bg: var(--xy-day-paper);
    --xy-key-line: rgba(26, 26, 26, 0.5);
    --xy-key-sh: #8C8C82;

    
    --white20a: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
    --white30a: color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);
    --white50a: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, transparent);
    --white60a: color-mix(in srgb, var(--SmartThemeBodyColor) 85%, transparent);
    --white70a: color-mix(in srgb, var(--SmartThemeBodyColor) 90%, transparent);
    --black30a: color-mix(in srgb, var(--SmartThemeBodyColor) 5%, transparent);
    --black50a: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
    --black60a: color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent);
    --black70a: color-mix(in srgb, var(--SmartThemeBodyColor) 12%, transparent);
    --grey30a: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
    --interactable-outline-color: var(--SmartThemeBodyColor);
    --interactable-outline-color-faint: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
}

:root:not(.dn-night) #nonQRFormItems {
